<script setup>
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import { subjects } from '../catalog'
const route = useRoute()
const search = ref(''), category = ref('All courses'), active = ref(null)
const filtered = computed(()=>subjects.filter(c=>(category.value==='All courses'||c.category===category.value)&&`${c.name} ${c.code} ${c.instructor}`.toLowerCase().includes(search.value.toLowerCase())))
if (route.query.course !== undefined) active.value = subjects[Number(route.query.course)] || null
</script>
<template><div class="page-heading"><div><div class="eyebrow">YOUR PERSONAL CURRICULUM</div><h1>Keep your curiosity going.</h1><p>Four courses. A semester full of possibilities.</p></div><a-tag color="green">Fall semester</a-tag></div><div class="toolbar"><a-input-search v-model:value="search" placeholder="Search courses or instructors" allow-clear style="max-width:360px"/><a-select v-model:value="category" style="width:200px" :options="['All courses',...new Set(subjects.map(c=>c.category))].map(value=>({value,label:value}))" aria-label="Course category" /></div><div class="course-grid"><article class="course-card" v-for="course in filtered" :key="course.code"><div class="course-cover" :style="{background:course.color}"><span>{{course.code}}</span><strong>{{course.icon}}</strong><small>FALL / CAMPUS</small></div><div class="course-body"><a-tag>{{course.category}}</a-tag><h2>{{course.name}}</h2><p>{{course.instructor}}</p><div class="course-meta"><span>8 learning modules</span><span>Self-paced</span></div><a-button block @click="active=course">View course details ↗</a-button></div></article></div><a-empty v-if="!filtered.length" description="No courses match your search"/><a-modal :open="!!active" :title="active?.name" @cancel="active=null" :footer="null"><template v-if="active"><p>{{active.code}} · {{active.category}}</p><p>Instructor: {{active.instructor}}</p><p>This demonstration course includes eight modules. Review the learning plan below, then manage your study tasks on the Assignments page.</p><a-list :data-source="['Foundations and key concepts','Tools and practical examples','Guided exercises','Independent practice','Applied techniques','Project workshop','Review and feedback','Final project']" size="small"><template #renderItem="{item,index}"><a-list-item>{{index+1}}. {{item}}</a-list-item></template></a-list><router-link to="/assignments"><a-button type="primary" style="margin-top:20px">Go to assignments</a-button></router-link></template></a-modal><p class="data-note">Illustrative course catalog for the SIS 4 dashboard.</p></template>
